#!/usr/bin/env bash
# PiTV Mini V2 in-place upgrade. Does not touch Chromium profile/Widevine.
set -euo pipefail
if (( EUID == 0 )); then echo 'Run as your normal Pi user, not sudo.'; exit 1; fi
DIR="$HOME/pi-tv"
if [[ ! -s "$DIR/remote-token" || ! -f "$DIR/start.sh" ]]; then echo 'PiTV Mini installation was not found at ~/pi-tv'; exit 1; fi
for cmd in python3 wtype chromium; do
  if ! command -v "$cmd" >/dev/null 2>&1; then
    if [[ "$cmd" == "chromium" ]] && command -v chromium-browser >/dev/null 2>&1; then continue; fi
    echo "Missing command: $cmd"; exit 1
  fi
done
STAMP="$(date +%Y%m%d-%H%M%S)"
BACK="$DIR/backups/$STAMP"
mkdir -p "$BACK" "$DIR/dpad-extension"
for f in remote.py tv-home.html phone-remote.html start.sh; do
  [[ ! -f "$DIR/$f" ]] || cp -p "$DIR/$f" "$BACK/$f"
done
# remote.py
base64 -d > "$DIR/remote.py" <<'PAYLOAD_remote_py'

PAYLOAD_remote_py
# tv-home.html
base64 -d > "$DIR/tv-home.html" <<'PAYLOAD_tv_home_html'

PAYLOAD_tv_home_html
# phone-remote.html
base64 -d > "$DIR/phone-remote.html" <<'PAYLOAD_phone_remote_html'

PAYLOAD_phone_remote_html
# start.sh
base64 -d > "$DIR/start.sh" <<'PAYLOAD_start_sh'

PAYLOAD_start_sh
# dpad-manifest.json
base64 -d > "$DIR/dpad-extension/manifest.json" <<'PAYLOAD_dpad_manifest_json'

PAYLOAD_dpad_manifest_json
# navigation.js
base64 -d > "$DIR/dpad-extension/navigation.js" <<'PAYLOAD_navigation_js'

PAYLOAD_navigation_js
chmod +x "$DIR/start.sh"
python3 -m py_compile "$DIR/remote.py"
printf '\nPiTV Mini V2 installed. BACKUP: %s\n' "$BACK"
printf 'REBOOT NOW: sudo reboot\n'
printf 'The existing Android remote URL and token are unchanged.\n'
